"""Special-Equivalent Groups with 1000 words of length 20, generated by shuffling even and odd
positions of a few bases (big groups) or at random."""

from string import ascii_lowercase

from _shapes import random_string

SEEDS = 2


def generate(rng):
    length = rng.choice([20, 19])
    alpha = ascii_lowercase[: rng.choice([2, 26])]
    bases = [random_string(rng, alpha, length) for _ in range(rng.choice([5, 300]))]
    words = []
    for _ in range(1000):
        w = list(rng.choice(bases))
        even, odd = w[0::2], w[1::2]
        rng.shuffle(even)
        rng.shuffle(odd)
        w[0::2], w[1::2] = even, odd
        words.append("".join(w))
    return {"words": words}
